                if (connectionElapsed >= 1 / 20 && shouldRebuildConnections(activeAudio, connectionState, lastConnectionState, idleConnectionElapsed)) {
                    const refreshSelection = !lastConnectionState || connectionState[2] !== lastConnectionState[2]
                        || connectionState[5] !== lastConnectionState[5] || (!activeAudio && idleConnectionElapsed >= 2);
                    updateConnections(
                        STATE.connectionThreshold,
                        activeAudio ? material.uniforms.uBass.value : 0,
                        activeAudio ? material.uniforms.uHighMid.value : 0,
                        activeAudio ? material.uniforms.uMid.value : 0,
                        refreshSelection
                    );
                    lastConnectionState = connectionState;
                    connectionElapsed = 0;
                    idleConnectionElapsed = 0;
                }
                connectionMaterial.uniforms.uBeatEnergy.value = material.uniforms.uBeatEnergy.value;
                connectionMaterial.uniforms.uHighMid.value = material.uniforms.uHighMid.value;
                connectionMaterial.uniforms.uSpectralCentroid.value = material.uniforms.uSpectralCentroid.value;
